def write(path, rows):
    with Path(path).open("w", encoding="utf-8", newline="") as f:
        w=csv.DictWriter(f, fieldnames=["id","text","label","source","difficulty","ambiguous"]); w.writeheader(); w.writerows(rows)
def main():
    ec=[]
    for label, texts in EC.items():
        for n,text in enumerate(texts,1): ec.append({"id":f"ec-{label}-{n:02d}","text":text,"label":label,"source":"synthetic","difficulty":"clear" if n<=12 else "subtle","ambiguous":"false"})
        for n,text in enumerate(AMB[label],22): ec.append({"id":f"ec-{label}-{n:02d}","text":text,"label":label,"source":"synthetic","difficulty":"ambiguous","ambiguous":"true"})
    sm=[]
    for label,texts in SMS.items():
        for n,text in enumerate(texts,1): sm.append({"id":f"sms-{label}-{n:02d}","text":text,"label":label,"source":"synthetic","difficulty":"clear" if n<=9 else "subtle","ambiguous":"false"})
    write("data/ecommerce_labeled.csv",ec); write("data/sms_labeled.csv",sm)
if __name__ == "__main__": main()
